"""Lexical experiments library (scratch). Self-contained, stdlib only."""
import json, math, re
from collections import Counter, defaultdict

W = '/workspace/.claude/worktrees/agent-afac2a73a7717fac3/case/'


def load():
    cat = [json.loads(l) for l in open(W + 'assets/catalog.jsonl')]
    tr = [json.loads(l) for l in open(W + 'dataset/train.jsonl')]
    meta = {}
    for l in open(W + 'dataset/train.meta.jsonl'):
        d = json.loads(l); meta[d['id']] = d
    curve = {json.loads(l)['id'] for l in open(W + 'dataset/train_curve.jsonl')}
    cfam = {meta[i]['family'] for i in curve}
    for e in tr:
        e['m'] = meta[e['id']]
        r = json.loads(e['reference']); e['rel'] = {r['primary'], *r['acceptable']}
        e['curve'] = e['m']['family'] in cfam
    return cat, tr


def score_one(ranked, rel):
    a = float(bool(ranked) and ranked[0] in rel)
    n = len(set(ranked[:3]) & rel) / min(3, len(rel))
    return 0.7 * a + 0.3 * n, a, n


def evaluate(rank_fn, tr, subset=None):
    """rank_fn(query)->list of ids. returns dict of slice->(score,acc,np,n)"""
    groups = defaultdict(list)
    for e in tr:
        if subset and not subset(e):
            continue
        r = rank_fn(e['input'])[:3]
        s = score_one(r, e['rel'])
        groups['all'].append(s)
        groups['style=' + e['m']['style']].append(s)
    out = {}
    for k, v in groups.items():
        n = len(v)
        out[k] = (sum(x[0] for x in v) / n, sum(x[1] for x in v) / n, sum(x[2] for x in v) / n, n)
    return out


def show(name, res):
    keys = ['all'] + sorted(k for k in res if k.startswith('style='))
    print(f"{name:34s} " + ' '.join(f"{k.replace('style=',''):>8s}" for k in keys))
    print(f"{'':34s} " + ' '.join(f"{res[k][0]:8.3f}" for k in keys))


# ---------------- Porter stemmer (own implementation) ----------------
class Porter:
    def __init__(self):
        self.cache = {}

    @staticmethod
    def _cons(w, i):
        c = w[i]
        if c in 'aeiou':
            return False
        if c == 'y':
            return i == 0 or not Porter._cons(w, i - 1)
        return True

    @classmethod
    def _m(cls, w):
        n = 0; i = 0; L = len(w)
        while i < L and cls._cons(w, i): i += 1
        while i < L:
            while i < L and not cls._cons(w, i): i += 1
            if i >= L: break
            n += 1
            while i < L and cls._cons(w, i): i += 1
        return n

    @classmethod
    def _vowel(cls, w):
        return any(not cls._cons(w, i) for i in range(len(w)))

    @classmethod
    def _dc(cls, w):
        return len(w) >= 2 and w[-1] == w[-2] and cls._cons(w, len(w) - 1)

    @classmethod
    def _cvc(cls, w):
        L = len(w)
        return L >= 3 and cls._cons(w, L - 1) and not cls._cons(w, L - 2) and cls._cons(w, L - 3) and w[-1] not in 'wxy'

    def stem(self, w):
        if w in self.cache: return self.cache[w]
        r = self._stem(w); self.cache[w] = r; return r

    def _stem(self, w):
        if len(w) <= 2 or not w.isalpha(): return w
        m, V, dc, cvc = self._m, self._vowel, self._dc, self._cvc
        if w.endswith('sses'): w = w[:-2]
        elif w.endswith('ies'): w = w[:-2]
        elif w.endswith('ss'): pass
        elif w.endswith('s'): w = w[:-1]
        flag = False
        if w.endswith('eed'):
            if m(w[:-3]) > 0: w = w[:-1]
        elif w.endswith('ed') and V(w[:-2]): w = w[:-2]; flag = True
        elif w.endswith('ing') and V(w[:-3]): w = w[:-3]; flag = True
        if flag:
            if w.endswith(('at', 'bl', 'iz')): w += 'e'
            elif dc(w) and w[-1] not in 'lsz': w = w[:-1]
            elif m(w) == 1 and cvc(w): w += 'e'
        if w.endswith('y') and V(w[:-1]): w = w[:-1] + 'i'
        s2 = [('ational', 'ate'), ('tional', 'tion'), ('enci', 'ence'), ('anci', 'ance'), ('izer', 'ize'), ('abli', 'able'), ('alli', 'al'), ('entli', 'ent'), ('eli', 'e'), ('ousli', 'ous'), ('ization', 'ize'), ('ation', 'ate'), ('ator', 'ate'), ('alism', 'al'), ('iveness', 'ive'), ('fulness', 'ful'), ('ousness', 'ous'), ('aliti', 'al'), ('iviti', 'ive'), ('biliti', 'ble')]
        for a, b in s2:
            if w.endswith(a):
                if m(w[:-len(a)]) > 0: w = w[:-len(a)] + b
                break
        s3 = [('icate', 'ic'), ('ative', ''), ('alize', 'al'), ('iciti', 'ic'), ('ical', 'ic'), ('ful', ''), ('ness', '')]
        for a, b in s3:
            if w.endswith(a):
                if m(w[:-len(a)]) > 0: w = w[:-len(a)] + b
                break
        s4 = ['al', 'ance', 'ence', 'er', 'ic', 'able', 'ible', 'ant', 'ement', 'ment', 'ent', 'ion', 'ou', 'ism', 'ate', 'iti', 'ous', 'ive', 'ize']
        for a in sorted(s4, key=len, reverse=True):
            if w.endswith(a):
                st = w[:-len(a)]
                if m(st) > 1 and (a != 'ion' or (st and st[-1] in 'st')): w = st
                break
        if w.endswith('e'):
            st = w[:-1]
            if m(st) > 1 or (m(st) == 1 and not cvc(st)): w = st
        if m(w) > 1 and dc(w) and w.endswith('l'): w = w[:-1]
        return w


STOP = set("a an and are as at be but by can could do does for from had has have how i if in into is it its just me my of on or our so some than that the their them then there these they this to up us was we were what when where which who why will with would you your pls please plz need want like get let help also any all about out over using use via".split())

_P = Porter()


def base_tokens(text, camel=True):
    if camel:
        text = re.sub(r'([a-z])([A-Z])', r'\1 \2', text)
    return re.findall(r'[a-z0-9]+', text.lower())


def make_tok(stem=True, stop=False, camel=True, keep_stop_if_only=True):
    def tok(text):
        ts = base_tokens(text, camel)
        if stop:
            f = [t for t in ts if t not in STOP]
            ts = f or ts
        if stem:
            ts = [_P.stem(t) for t in ts]
        return ts
    return tok


# ---------------- BM25F ----------------
class Index:
    def __init__(self, cat, tok, wname=1.0, wdesc=1.0, k1=1.5, b=0.75, bn=None, bd=None):
        self.cat, self.tok, self.k1 = cat, tok, k1
        self.ids = [c['id'] for c in cat]
        self.docs = []
        for c in cat:
            nt = tok(c['name']); dt = tok(c['description'])
            self.docs.append((nt, dt))
        bn = b if bn is None else bn
        bd = b if bd is None else bd
        self.wn, self.wd, self.bn, self.bd = wname, wdesc, bn, bd
        self.avn = sum(len(d[0]) for d in self.docs) / len(self.docs)
        self.avd = sum(len(d[1]) for d in self.docs) / len(self.docs)
        self.tf = []
        for nt, dt in self.docs:
            cn, cd = Counter(nt), Counter(dt)
            pseudo = {}
            for t in set(cn) | set(cd):
                pseudo[t] = (wname * cn[t] / (1 - bn + bn * len(nt) / self.avn) if cn[t] else 0.0) + \
                            (wdesc * cd[t] / (1 - bd + bd * len(dt) / self.avd) if cd[t] else 0.0)
            self.tf.append(pseudo)
        df = Counter(t for p in self.tf for t in p)
        n = len(cat)
        self.df = df
        self.idf = {t: math.log(1 + (n - f + 0.5) / (f + 0.5)) for t, f in df.items()}
        self.vocab = set(df)

    def scores(self, qtoks, qw=None):
        out = []
        for p in self.tf:
            s = 0.0
            for t in qtoks:
                x = p.get(t)
                if x:
                    s += (qw[t] if qw else 1.0) * self.idf[t] * x * (self.k1 + 1) / (x + self.k1)
            out.append(s)
        return out

    def rank(self, scores):
        return [self.ids[i] for i in sorted(range(len(scores)), key=lambda i: (-scores[i], i))]

