def lev1(a, b):
    """Damerau-Levenshtein <=1 test."""
    if a == b: return True
    la, lb = len(a), len(b)
    if abs(la - lb) > 1: return False
    if la == lb:
        diff = [i for i in range(la) if a[i] != b[i]]
        if len(diff) == 1: return True
        if len(diff) == 2 and diff[1] == diff[0] + 1 and a[diff[0]] == b[diff[1]] and a[diff[1]] == b[diff[0]]: return True
        return False
    if la > lb: a, b = b, a
    i = 0
    while i < len(a) and a[i] == b[i]: i += 1
    return a[i:] == b[i + 1:]


def ngrams(word, ns=(3,)):
    w = f'^{word}$'
    out = []
    for n in ns:
        out += [w[i:i + n] for i in range(len(w) - n + 1)]
    return out


class Sys:
    def __init__(self, cat, stop=STOP, extra_stop=(), stem=True, k1=1.2, b=0.75, wn=1.0,
                 fuzzy=0.0, fuzzy_min=5, ng=0.0, ng_ns=(3,), bigram=0.0, prf=0.0, prf_k=3, prf_terms=8,
                 dedup=False, idf_pow=1.0, ng_agg='cos'):
        self.cat = cat
        self.stop = set(stop) | set(extra_stop)
        self.stem = stem
        self.fuzzy, self.fuzzy_min, self.ng, self.ng_ns = fuzzy, fuzzy_min, ng, ng_ns
        self.bigram, self.prf, self.prf_k, self.prf_terms = bigram, prf, prf_k, prf_terms
        self.dedup, self.idf_pow = dedup, idf_pow
        self.tok = self._tok
        self.ix = Index(cat, self._tok, wname=wn, k1=k1, b=b)
        self.ids = self.ix.ids
        # raw (unstemmed) vocab for fuzzy
        self.raw_vocab = Counter()
        for c in cat:
            for t in self._words(c['name'] + ' ' + c['description']):
                self.raw_vocab[t] += 1
        self.rawv = [w for w in self.raw_vocab if len(w) >= 4 and w not in self.stop]
        # bigram index
        if bigram:
            self.big = []
            for nt, dt in self.ix.docs:
                s = Counter()
                for seq in (nt, dt):
                    for i in range(len(seq) - 1): s[(seq[i], seq[i + 1])] += 1
                self.big.append(s)
            dfb = Counter(g for s in self.big for g in s)
            n = len(cat)
            self.bidf = {g: math.log(1 + (n - f + .5) / (f + .5)) for g, f in dfb.items()}
        if ng:
            docs = []
            for c in cat:
                grams = Counter()
                for w in self._words(c['name'] + ' ' + c['description']):
                    if w in self.stop: continue
