                docs.append(grams)
            dfn = Counter(g for d in docs for g in d)
            n = len(cat)
            self.nidf = {g: math.log(1 + n / f) for g, f in dfn.items()}
            self.nvec = []
            for d in docs:
                v = {g: (1 + math.log(c)) * self.nidf[g] for g, c in d.items()}
                nrm = math.sqrt(sum(x * x for x in v.values())) or 1
                self.nvec.append({g: x / nrm for g, x in v.items()})

    def _words(self, text):
        return re.findall(r'[a-z0-9]+', text.lower())

    def _tok(self, text):
        ts = self._words(text)
        f = [t for t in ts if t not in self.stop]
        ts = f or ts
        if self.stem:
            ts = [_P.stem(t) for t in ts]
        return ts

    def qtokens(self, q):
        words = self._words(q)
        f = [t for t in words if t not in self.stop]
        words = f or words
        out = []
        weights = {}
        for w in words:
            st = _P.stem(w) if self.stem else w
            if st in self.ix.vocab:
                out.append(st); weights[st] = max(weights.get(st, 0), 1.0)
            elif self.fuzzy and len(w) >= self.fuzzy_min and w.isalpha():
                cands = [v for v in self.rawv if lev1(w, v) and v[0] == w[0]] or [v for v in self.rawv if lev1(w, v)]
                if cands:
                    best = max(cands, key=lambda v: self.raw_vocab[v])
                    st2 = _P.stem(best) if self.stem else best
                    if st2 in self.ix.vocab:
                        out.append(st2); weights[st2] = max(weights.get(st2, 0), self.fuzzy)
            else:
                out.append(st)
        if self.dedup:
            seen = []; [seen.append(t) for t in out if t not in seen]; out = seen
        return out, weights

    def raw_scores(self, q):
        qt, w = self.qtokens(q)
        s = self.ix.scores(qt, {t: w.get(t, 1.0) for t in qt})
        return qt, s

    def score(self, q):
        qt, s = self.raw_scores(q)
        s = list(s)
        if self.bigram:
            ws = [t for t in self._tok(q)]
            bg = set(zip(ws, ws[1:]))
            for i, d in enumerate(self.big):
                for g in bg:
                    if g in d: s[i] += self.bigram * self.bidf[g]
        if self.prf:
            top = sorted(range(len(s)), key=lambda i: -s[i])[:self.prf_k]
            if s[top[0]] > 0:
                mx = s[top[0]]
                exp = Counter()
                for r, i in enumerate(top):
                    wgt = s[i] / mx
                    for t, x in self.ix.tf[i].items():
                        exp[t] += wgt * self.ix.idf[t] * x
                for t in qt: exp.pop(t, None)
