                s = [a + scale * b / (max(es) or 1) * (max(es) or 1) / (max(es) or 1) for a, b in zip(s, es)]
        if self.ng:
            grams = Counter()
            for w in self._words(q):
                if w in self.stop: continue
                grams.update(ngrams(w, self.ng_ns))
            v = {g: (1 + math.log(c)) * self.nidf.get(g, 0) for g, c in grams.items()}
            nrm = math.sqrt(sum(x * x for x in v.values())) or 1
            mx = max(s) or 1
            cs = []
            for d in self.nvec:
                cs.append(sum(x * d.get(g, 0) for g, x in v.items()) / nrm)
