            while i < size and not cls._cons(w, i):
                i += 1
            if i >= size:
                break
            n += 1
            while i < size and cls._cons(w, i):
                i += 1
        return n

    @classmethod
    def _vowel(cls, w):
        return any(not cls._cons(w, i) for i in range(len(w)))

    @classmethod
    def _dc(cls, w):
        return len(w) >= 2 and w[-1] == w[-2] and cls._cons(w, len(w) - 1)

