                if m(w[:-len(a)]) > 0:
                    w = w[:-len(a)] + b
                break
        for a in self.S4:
            if w.endswith(a):
                st = w[:-len(a)]
                if m(st) > 1 and (a != "ion" or (st and st[-1] in "st")):
                    w = st
